/**
 * Builds a hierarchical structure from a flat list of heading elements
 * @param {HTMLElement[]} elements - Array of heading elements to structure
 * @param {string} liClass - CSS classes for list items
 * @param {string} aClass - CSS classes for anchors
 * @return {Object[]} Hierarchical array of items with nested children
 * @property {string} return[].href - Anchor link to the heading
 * @property {string} return[].label - Text content of the heading
 * @property {string} return[].liClass - CSS classes for the list item
 * @property {string} return[].aClass - CSS classes for the anchor
 * @property {Object[]} return[].children - Nested child items
 */

export function buildStructure(elements, liClass, aClass) {
  const structure = []
  const stack = [{ headingLevel: 0, children: structure }]

  elements.forEach(element => {
    const headingLevel = parseInt(element.tagName.charAt(1))
    const item = {
      href: `#${element.id}`,
      label: element.textContent,
      liClass,
      aClass,
      children: [],
    }

    while (headingLevel <= stack[stack.length - 1].headingLevel) {
      stack.pop()
    }

    stack[stack.length - 1].children.push(item)
    stack.push({ headingLevel, children: item.children })
  })

  return structure
}

/**
 * Recursively updates aria-current attribute for items matching the target href
 * @param {Object[]} items - Array of content list items to process
 * @param {string} targetHref - Target href to mark as current location
 * @return {Object[]} Updated array with aria-current attributes set
 * @property {string|null} return[].aria-current - 'location' if item matches targetHref, null otherwise
 */
export function updateAriaCurrent(items, targetHref) {
  return items.map(item => {
    const newItem = { ...item }
    if (item.href === targetHref) {
      newItem['aria-current'] = 'location'
    } else {
      newItem['aria-current'] = null
    }
    if (item.children && item.children.length > 0) {
      newItem.children = updateAriaCurrent(item.children, targetHref)
    }
    return newItem
  })
}
